"""Import only verified artifacts; attach source/run provenance and current source hashes."""
import json,pathlib,shutil,sys,hashlib
p=pathlib.Path(sys.argv[1]);out=pathlib.Path('web/evidence')
s=json.loads((p/'system.json').read_text());f=json.loads((p/'formal-depth.json').read_text())
assert s['configurations']==48 and s['cases']==384
assert len(f['proofs'])==4
assert len(s['mutations'])==2 and all(m['detected'] for m in s['mutations'])
for file,digest in s['rtl_sha256'].items():assert hashlib.sha256(pathlib.Path('rtl',file).read_bytes()).hexdigest()==digest
for name in ['system.json','formal-depth.json','digits.json','ml-vectors.json','system-synthesis.log','system-netlist-simulation.log']+[r['log'] for r in f['proofs']]:shutil.copy(p/name,out/name)
manifest=dict(run_url=sys.argv[2],source_commit=(p/'commit.txt').read_text().strip(),files={name:hashlib.sha256((p/name).read_bytes()).hexdigest() for name in ['system.json','formal-depth.json','digits.json','ml-vectors.json']},scope='Generated by the remote integrated evidence workflow. The model report includes canonical data hashes and split indices.')
(out/'integrated-provenance.json').write_text(json.dumps(manifest,indent=2));print(manifest)
